        # 78 watering wilting plant near window
        ("Mr Thistlewaite", "Lan, the plant near the window looks like it's wilting, could you give it some water?", "Chị Lan, cây gần cửa sổ trông như đang héo, chị tưới nước giúp được không?"),
        ("Ms Lan", "I'll water it now and move it slightly away from the direct sun.", "Tôi sẽ tưới ngay và dời nó ra một chút khỏi ánh nắng trực tiếp."),
        ("Mr Thistlewaite", "Good idea, direct sun through that window is pretty strong in the afternoon.", "Ý hay đấy, ánh nắng trực tiếp qua cửa sổ đó khá mạnh vào buổi chiều."),
        # 79 ice made from filtered water
        ("Ms Lan", "Thistlewaite, a customer asked if the ice in her drink is made from filtered water.", "Anh Thistlewaite, một khách hỏi đá trong ly của cô ấy có được làm từ nước lọc không."),
        ("Mr Thistlewaite", "Yes, tell her the ice machine runs off the same filtered line as our drinking water.", "Có, chị nói với cô ấy máy làm đá dùng chung đường nước lọc với nước uống của bọn mình."),
        ("Ms Lan", "Good, that answer should put her at ease right away.", "Tốt, câu trả lời đó sẽ khiến cô ấy yên tâm ngay."),
        # 80 kitchen hot water not working
        ("Mr Thistlewaite", "Lan, the kitchen's hot water isn't working, we can't make any tea orders right now.", "Chị Lan, nước nóng trong bếp không hoạt động, bọn mình không thể pha trà lúc này."),
        ("Ms Lan", "Let me check the water heater switch, sometimes it just trips during busy hours.", "Để tôi kiểm tra công tắc máy nước nóng, đôi khi nó chỉ bị ngắt trong giờ cao điểm."),
        ("Mr Thistlewaite", "Good idea, let me know if that fixes it or if we need a technician.", "Ý hay đấy, chị báo tôi nếu điều đó khắc phục được hoặc nếu mình cần thợ."),
